const require_index = require("../useSupported/index.js");
let react = require("react");
//#region src/useBroadcastChannel/index.ts
const useBroadcastChannel = (options) => {
	const { name } = options;
	const isSupported = require_index.useSupported(() => window && "BroadcastChannel" in window);
	const [isClosed, setIsClosed] = (0, react.useState)(false);
	const [data, setData] = (0, react.useState)();
	const [error, setError] = (0, react.useState)(null);
	const [timeStamp, setTimeStamp] = (0, react.useState)(0);
	const channelRef = (0, react.useRef)();
	const post = (0, react.useCallback)((data) => {
		if (channelRef.current) channelRef.current.postMessage(data);
	}, []);
	const close = (0, react.useCallback)(() => {
		if (channelRef.current) channelRef.current.close();
		setIsClosed(true);
	}, []);
	(0, react.useEffect)(() => {
		if (isSupported) {
			channelRef.current = new BroadcastChannel(name);
			setError(null);
			const handleMessage = (e) => {
				setData(e.data);
				setTimeStamp(Date.now());
			};
			const handleError = (e) => {
				setError(e);
			};
			const handleClose = () => {
				setIsClosed(true);
			};
			channelRef.current.addEventListener("message", handleMessage, { passive: true });
			channelRef.current.addEventListener("messageerror", handleError, { passive: true });
			channelRef.current.addEventListener("close", handleClose);
			return () => {
				if (channelRef.current) {
					channelRef.current.removeEventListener("message", handleMessage);
					channelRef.current.removeEventListener("messageerror", handleError);
					channelRef.current.removeEventListener("close", handleClose);
					close();
				}
			};
		}
		return close;
	}, [
		isSupported,
		name,
		close
	]);
	return {
		isSupported,
		channel: channelRef.current,
		data,
		post,
		close,
		error,
		isClosed,
		timeStamp
	};
};
//#endregion
exports.useBroadcastChannel = useBroadcastChannel;
